package findu.backend.founditem.entity;
import findu.backend.category.entity.Category; import findu.backend.global.entity.BaseEntity; import findu.backend.user.entity.User; import jakarta.persistence.*; import lombok.*; import java.time.LocalDateTime;
@Entity @Getter @Builder @NoArgsConstructor(access=AccessLevel.PROTECTED) @AllArgsConstructor @Table(name="found_items") public class FoundItem extends BaseEntity { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="user_id") private User user; @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="category_id") private Category category; @Column(nullable=false,length=100) private String title; @Column(nullable=false,columnDefinition="TEXT") private String description; @Column(length=1000) private String imageUrl; @Column(length=255) private String location; @Column(nullable=false) private LocalDateTime foundAt; public void update(Category c,String t,String d,String i,String l,LocalDateTime f){category=c;title=t;description=d;imageUrl=i;location=l;foundAt=f;} }
